"""Second revision. Sensitivity analyses of Section 3.4 with the reference model generated by inversion,
replacing the rank-indexed generator and the 200 realizations of the first revision.

1. Resolution of the intensity: the reference model carries the cumulative intensity estimated with
   S = 2,000, 5,000, 20,000 and 100,000 gaps, and the Monte Carlo p-value of D_1000 (and of D_20000,
   for comparison) is computed against R realizations generated by inversion at each S.
2. Intensity from the counting function alone: the gaps of the numbers above 10^6 are divided by the
   mean gap 1/C0'(x) of the monotone interpolation C0 of log C against log x at quarter decades, and
   the distance to the exponential law is compared with R realizations of the Poisson process with
   mean measure C0, generated by inversion and passed through the same computation.

Usage: python code/25_sensitivity_inversion.py [R] [workers]
"""
import json
import os
import sys
import time
from multiprocessing import Pool

import numpy as np
from scipy.interpolate import PchipInterpolator

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import benchmark as B
from common import RESULTS, census_cache

R = int(sys.argv[1]) if len(sys.argv) > 1 else 2000
WORKERS = int(sys.argv[2]) if len(sys.argv) > 2 else 3
SEED = 20261017
GRID_S = (2000, 5000, 20000, 100000)
CHUNK = 25


def counting_function():
    n, _ = census_cache()
    grid = 10 ** np.arange(3, 18.01, 0.25)
    Cg = np.searchsorted(n, grid).astype(float)
    keep = Cg > 0
    f = PchipInterpolator(np.log(grid[keep]), np.log(Cg[keep]))
    return n, f, int(keep.sum())


def c0_distance(pos, f):
    """Distance to the exponential law of the gaps above 10^6 divided by the mean gap 1/C0'(x)."""
    g = np.diff(pos)
    logx = np.log(0.5 * (pos[:-1] + pos[1:]))
    sel = pos[:-1] >= 1e6
    with np.errstate(divide="ignore", invalid="ignore"):
        mean_gap = np.exp(logx - f(logx)) / f.derivative()(logx)
    u = g[sel] / mean_gap[sel]
    return B.sup_dev(u / u.mean(), B.exp_cdf), int(sel.sum()), float(u.mean()), float(u.std())


def work(task):
    kind, S, seed, reps = task
    rng = np.random.default_rng(seed)
    n, f, _ = counting_function()
    pos = n.astype(np.float64)
    out = []
    if kind == "S":
        xk, Lk = B.cumulative_intensity(pos, S)
        for _ in range(reps):
            g = B.gen_inverse(xk, Lk, len(pos), rng)
            out.append([B.sup_dev(g / B.rollmean(g, W), B.exp_cdf) for W in (1000, 20000)])
    else:
        xk = np.exp(np.linspace(np.log(pos[0]), np.log(pos[-1]), 400001))
        Lk = np.exp(f(np.log(xk)))
        Lk = Lk - Lk[0]
        for _ in range(reps):
            p = pos[0] + np.concatenate(([0.0], np.cumsum(B.gen_inverse(xk, Lk, len(pos), rng))))
            out.append([c0_distance(p, f)[0]])
    return kind, S, np.array(out)


def main():
    t0 = time.time()
    n, f, checkpoints = counting_function()
    pos = n.astype(np.float64)
    g = np.diff(pos)
    obs = {W: B.sup_dev(g / B.rollmean(g, W), B.exp_cdf) for W in (1000, 20000)}
    D0, n_gaps, m0, s0 = c0_distance(pos, f)
    seq = np.random.SeedSequence(SEED)
    tasks = [("S", S, c.generate_state(1)[0], CHUNK) for S in GRID_S for c in seq.spawn(R // CHUNK)]
    tasks += [("C0", 0, c.generate_state(1)[0], CHUNK) for c in seq.spawn(R // CHUNK)]
    draws = {}
    with Pool(WORKERS) as pool:
        for kind, S, arr in pool.imap_unordered(work, tasks):
            draws.setdefault((kind, S), []).append(arr)
    draws = {k: np.vstack(v) for k, v in draws.items()}
    out = dict(R=R, seed=SEED, resolution={}, counting_function={})
    for S in GRID_S:
        d = draws[("S", S)]
        row = {}
        for j, W in enumerate((1000, 20000)):
            p = B.mc_pvalue(obs[W], d[:, j], False)
            row[str(W)] = dict(obs=obs[W], null_mean=float(d[:, j].mean()), q95=float(np.quantile(d[:, j], 0.95)),
                               p=float(p), p_se=float(B.mc_se(p, len(d))))
        out["resolution"][str(S)] = row
        print(f"S={S:6d}  " + "  ".join(f"W={W}: p={row[W]['p']:.3f}" for W in row), flush=True)
    d = draws[("C0", 0)][:, 0]
    p = B.mc_pvalue(D0, d, False)
    out["counting_function"] = dict(checkpoints=checkpoints, n_gaps=n_gaps, mean=m0, sd=s0, D=D0,
                                    null_mean=float(d.mean()), q95=float(np.quantile(d, 0.95)), p=float(p),
                                    p_se=float(B.mc_se(p, len(d))))
    print(f"counting function: D={D0:.5f} q95={np.quantile(d, 0.95):.5f} p={p:.3f}", flush=True)
    out["elapsed_s"] = time.time() - t0
    with open(os.path.join(RESULTS, "25_sensitivity_inversion.json"), "w") as fh:
        json.dump(out, fh, indent=1)
    print(f"done in {out['elapsed_s']:.0f}s")


if __name__ == "__main__":
    main()
